<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import PrefCard from '../PrefCard.vue'; import PrefRow from '../PrefRow.vue';
import { MODEL_ROUTING_IPC, type ModelClass, type ModelRoutingState, type RoutingProviderInfo } from '@pkg/agent/languagemodels/modelRoutingTypes';
import { useSullaSetting } from '@pkg/composables/preferences/useSullaSetting'; import { ipcRenderer } from '@pkg/utils/ipcRenderer';
import ModelClasses from './modelRouting/ModelClasses.vue'; import RoutingList from './modelRouting/RoutingList.vue'; import { CLASS_LABELS, traceRoute } from './modelRouting/routingLogic';
const state = ref<ModelRoutingState | null>(null); const unavailable = ref(false); const error = ref(''); const saved = ref(false); const traceList = ref<'agents'|'subconscious'>('agents');
const retries = useSullaSetting('remoteRetryCount', 3, 'number'); const timeout = useSullaSetting('remoteTimeoutSeconds', 60, 'number');
let timer: ReturnType<typeof setTimeout> | undefined; let snapshot = '';
function clone<T>(x: T): T { return JSON.parse(JSON.stringify(x)); }
async function load() { try { state.value = await ipcRenderer.invoke(MODEL_ROUTING_IPC.get); snapshot = JSON.stringify(state.value); } catch { unavailable.value = true; } }
function save(patch: Partial<Pick<ModelRoutingState, 'agentsList'|'subconsciousList'|'classes'|'followProviderOrder'>>) { if (!state.value) return; error.value = ''; clearTimeout(timer); timer = setTimeout(async() => { const before = snapshot; try { const next = await ipcRenderer.invoke(MODEL_ROUTING_IPC.set, patch); state.value = next; snapshot = JSON.stringify(next); saved.value = true; setTimeout(() => saved.value = false, 1800); } catch (e) { state.value = JSON.parse(before); error.value = `Couldn't save model routing: ${e instanceof Error ? e.message : String(e)}`; } }, 300); }
function setList(key: 'agentsList'|'subconsciousList', rows: ModelRoutingState[typeof key]) { if (!state.value) return; state.value[key] = rows; save({ [key]: clone(rows) }); }
function setModels(c: ModelClass, models: ModelRoutingState['classes'][ModelClass]) { if (!state.value) return; state.value.classes[c] = models; save({ classes: clone(state.value.classes) }); }
function setFollow(c: ModelClass, value: boolean) { if (!state.value) return; state.value.followProviderOrder[c] = value; save({ followProviderOrder: clone(state.value.followProviderOrder) }); }
async function reset(section: 'agents'|'subconscious'|'classes', modelClass?: ModelClass) { if (!state.value) return; try { state.value = await ipcRenderer.invoke(MODEL_ROUTING_IPC.reset, { section, class: modelClass }); snapshot = JSON.stringify(state.value); saved.value = true; } catch(e) { error.value = String(e); } }
function status(_: unknown, providers: RoutingProviderInfo[]) { if (state.value) state.value.providers = providers; }
const trace = computed(() => state.value ? traceRoute(state.value, traceList.value) : []);
function value(e: Event) { return (e.target as HTMLInputElement).value; } async function saveNumber(setting: typeof retries, raw: string, min: number, max: number) { const n = Math.round(Number(raw)); if (Number.isFinite(n) && n >= min && n <= max) await setting.save(n); else await setting.reload(); }
onMounted(() => { load(); ipcRenderer.on(MODEL_ROUTING_IPC.status, status); }); onBeforeUnmount(() => { clearTimeout(timer); ipcRenderer.removeListener(MODEL_ROUTING_IPC.status, status); });
</script>
<template><div><div class="ph"><div><h1>AI models</h1><p>Choose the providers and model classes your agents try, in order.</p></div><span v-if="saved" class="saved" role="status">Saved</span></div>
  <p v-if="error" class="error-banner">{{ error }}</p><div v-if="unavailable" class="backend-notice"><b>Model routing needs the latest Sulla backend.</b><span>Update Sulla, then return here to configure provider fallback.</span></div>
  <template v-else-if="state"><RoutingList title="Agents" subtitle="Your main agents walk this list from top to bottom until a model is ready." :state="state" :rows="state.agentsList" @update="setList('agentsList', $event)" @reset="reset('agents')" />
    <RoutingList title="Subconscious agents" subtitle="Background agents that read and organize conversations. Keep these cheap and fast so they never compete with main agents." :state="state" :rows="state.subconsciousList" @update="setList('subconsciousList', $event)" @reset="reset('subconscious')" />
    <ModelClasses :state="state" @models="setModels" @follow="setFollow" @reset="reset('classes', $event)" />
    <section class="route-card explainer"><header><div><h2>How a request is routed</h2><p>See the live fallback path from your settings above.</p></div><div class="segment"><button :class="{ on: traceList === 'agents' }" @click="traceList = 'agents'">Agent</button><button :class="{ on: traceList === 'subconscious' }" @click="traceList = 'subconscious'">Subconscious</button></div></header><p>A request walks its list top to bottom. Sulla skips rows that are off, missing a model, cooling down or erroring, then uses the first ready model.</p><ol class="trace"><li v-for="(step, i) in trace" :key="i" :class="step.result"><span>{{ i + 1 }}</span><b>{{ state.providers.find(p => p.id === step.row.provider)?.name }}</b><em>{{ CLASS_LABELS[step.row.class] }}</em><code>{{ step.model?.model ?? 'no model' }}</code><strong>{{ step.result === 'use' ? 'Use this model' : `Skip · ${step.result}` }}</strong></li></ol></section>
  </template>
  <PrefCard title="Request settings"><PrefRow title="Retries" subtitle="How many times Sulla retries a failed remote request."><input class="inp sm" type="number" min="0" max="10" :value="retries.value.value" @change="saveNumber(retries, value($event), 0, 10)"></PrefRow><PrefRow title="Time limit" subtitle="Seconds before a remote request gives up."><input class="inp sm" type="number" min="5" max="600" :value="timeout.value.value" @change="saveNumber(timeout, value($event), 5, 600)"> <span class="dimc">seconds</span></PrefRow></PrefCard>
</div></template>
<style scoped>
