:deep(.route-card){margin-bottom:14px;border:1px solid var(--border);border-radius:12px;background:var(--surface-1);box-shadow:0 1px 2px color-mix(in srgb,var(--text) 6%,transparent);overflow:visible}:deep(.route-card>header){display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:17px 18px;border-bottom:1px solid var(--border-muted)}:deep(.route-card h2){margin:0;color:var(--text);font-size:16px}:deep(.route-card header p){margin:4px 0 0;color:var(--text-muted);font-size:13px}:deep(.provider-list){list-style:none;margin:0;padding:8px}:deep(.provider-list li){display:grid;grid-template-columns:28px 24px minmax(140px,1fr) minmax(180px,1fr) auto auto auto;align-items:center;gap:9px;padding:10px 8px;border-bottom:1px solid var(--border-muted)}:deep(.provider-list li:last-child){border:0}:deep(.provider-list li.skipped){opacity:.58}:deep(button){font:inherit}:deep(.grip){border:0;background:none;color:var(--text-dim);cursor:grab}:deep(.rank){color:var(--text-dim);font:12px var(--font-mono)}:deep(.identity){display:flex;min-width:0;flex-direction:column}:deep(.identity b){color:var(--text);font-size:13px}:deep(.identity small),:deep(.resolution small){overflow:hidden;color:var(--text-muted);font-size:11px;text-overflow:ellipsis;white-space:nowrap}:deep(.resolution){display:flex;min-width:0;flex-direction:column;gap:3px}:deep(select){padding:5px 25px 5px 8px;border:1px solid var(--border);border-radius:7px;background:var(--surface-2);color:var(--text)}:deep(.status){padding:4px 8px;border:1px solid color-mix(in srgb,var(--success) 30%,var(--border));border-radius:999px;background:color-mix(in srgb,var(--success) 10%,var(--surface-1));color:var(--text);font-size:11px;white-space:nowrap}:deep(.status[data-status="cooling"]){border-color:color-mix(in srgb,var(--warning) 45%,var(--border));background:color-mix(in srgb,var(--warning) 10%,var(--surface-1))}:deep(.status[data-status="error"]){border-color:color-mix(in srgb,var(--danger) 45%,var(--border));background:color-mix(in srgb,var(--danger) 8%,var(--surface-1))}:deep(.row-actions){display:flex}:deep(.row-actions button),:deep(.model-row button){border:0;background:none;color:var(--text-muted);cursor:pointer}:deep(.switch){display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-muted)}:deep(.switch input){position:absolute;opacity:0}:deep(.switch span){width:28px;height:16px;border-radius:10px;background:var(--border);box-shadow:inset 0 0 0 1px var(--border)}:deep(.switch span:after){display:block;width:12px;height:12px;margin:2px;border-radius:50%;background:var(--surface-1);content:"";transition:.15s}:deep(.switch input:checked+span){background:var(--accent)}:deep(.switch input:checked+span:after){transform:translateX(12px)}:deep(.add-wrap){position:relative;padding:8px 16px 14px}:deep(.picker){position:absolute;z-index:5;display:flex;width:min(430px,calc(100vw - 80px));max-height:300px;flex-direction:column;overflow:auto;padding:8px;border:1px solid var(--border);border-radius:9px;background:var(--surface-2);box-shadow:0 8px 24px color-mix(in srgb,var(--text) 15%,transparent)}:deep(.picker>b){padding:7px}:deep(.picker button){display:flex;justify-content:space-between;padding:8px;border:0;border-radius:6px;background:none;color:var(--text);text-align:left}:deep(.picker button:hover){background:var(--surface-3)}:deep(.picker button:disabled){opacity:.45}:deep(.not-connected){display:flex;gap:14px;padding:10px 16px;border-top:1px solid var(--border-muted);color:var(--text-dim);font-size:12px}:deep(.not-connected span){opacity:.65}:deep(.single-hint){margin:10px 16px 0;padding:9px;border-radius:8px;background:var(--accent-dim);color:var(--text-muted);font-size:12px}
:deep(.class-row){border-bottom:1px solid var(--border-muted)}:deep(.class-head){display:flex;width:100%;align-items:center;gap:10px;padding:13px 18px;border:0;background:none;color:var(--text);text-align:left}:deep(.class-head small){margin-left:auto;overflow:hidden;color:var(--text-muted);text-overflow:ellipsis;white-space:nowrap}:deep(.class-body){padding:0 18px 15px}:deep(.order-switch){display:flex;align-items:center;gap:5px;margin-bottom:9px}:deep(.order-switch button),.segment button{padding:5px 9px;border:1px solid var(--border);background:var(--surface-1);color:var(--text-muted)}:deep(.order-switch button.on),.segment button.on{background:var(--accent-dim);color:var(--accent);font-weight:650}:deep(.order-switch span){margin-left:8px;color:var(--text-dim);font-size:11px}:deep(.model-row){display:grid;grid-template-columns:25px minmax(90px,.6fr) minmax(120px,1fr) 28px 28px 28px;align-items:center;gap:7px;padding:8px;border-top:1px solid var(--border-muted);font-size:12px}:deep(.model-row code){overflow:hidden;text-overflow:ellipsis}:deep(.empty){color:var(--text-muted);font-size:12px}:deep(.reset-one){float:right}:deep(.model-picker){position:relative;margin-top:5px}.explainer>p{padding:0 18px;color:var(--text-muted);font-size:13px}.segment{display:flex}.segment button:first-child{border-radius:7px 0 0 7px}.segment button:last-child{border-radius:0 7px 7px 0}.trace{list-style:none;margin:10px 18px 18px;padding:0;border:1px solid var(--border);border-radius:9px}.trace li{display:grid;grid-template-columns:25px 1fr 90px 1fr auto;gap:8px;padding:10px;border-bottom:1px solid var(--border-muted);font-size:12px}.trace li:last-child{border:0}.trace li strong{color:var(--text-muted)}.trace li.use{background:color-mix(in srgb,var(--success) 7%,transparent)}.trace li.use strong{color:var(--success)}
@media(max-width:1000px){:deep(.provider-list li){grid-template-columns:26px 22px 1fr auto auto}:deep(.resolution){grid-column:3/5}:deep(.status){grid-column:3/5;justify-self:start}:deep(.row-actions){grid-column:4;grid-row:1}:deep(.switch){grid-column:5;grid-row:1}.trace li{grid-template-columns:22px 1fr auto}.trace li code,.trace li strong{grid-column:2/4}}
</style>
